local machine = require("3rd.lua-state-machine.statemachine");

UserManager = {};
local this = UserManager;
local fsm = nil;
local loginCallback = nil;
local loginResponse = nil;

local AutoEnterGame = false;   -- 登录成功后，是否自动进入游戏（不用点击开始按钮）。

function UserManager.Init()
    fsm = machine.create({
        initial = 'idle',
        events = {
            { name = 'init',  from = 'idle',  to = 'init' },
            { name = 'auth',  from = 'init',  to = 'authing' },
            { name = 'login',  from = 'authing',  to = 'logining' },
            { name = 'done',  from = 'logining',  to = 'logined' },
        },
        callbacks = {
            --onbeforeinit = UserManager.OnBeforeInit,
            oninit = UserManager.OnInit,
            onauth = UserManager.OnAuth,
            onlogin = UserManager.OnLogin,
            ondone = UserManager.OnDone,
        }
    });
    --self.fsm = fsm;
    userSystem.onEventX = function(state, event, param)
        if event == UserSystem.Events.SDKLoginSuccess then
            Debug.LogWarning("是否已经登录:"..tostring(userSystem.Instance:HasLogined()));
            Debug.LogWarning("===>准备验证:"..param.."-状态:"..tostring(fsm.current));
            if AutoEnterGame == true then
                fsm:init();
            end
        elseif event == UserSystem.Events.SDKInitFailed or event == UserSystem.Events.SDKLoginFailed then
            uiSystem:PopDialogX(TextSystem.GetText("login_error"), TextSystem.GetText("login__error_description"), UIManager.DialogOption["Yes"], function(option)
                --UnityEngine.Application.Quit();
            end);
            --fsm:init();
        elseif event == UserSystem.Events.SDKPaySuccess then
            --uiSystem:PopDialogX(TextSystem.GetText("pay_success"), "支付成功", UIManager.DialogOption["Yes"], function(option)
            --end);
        elseif event == UserSystem.Events.SDKPayFailed or event == UserSystem.Events.SDKPayCancel then
            HttpNetworkManager.PayCancel(param);
            uiSystem:PopDialogX(TextSystem.GetText("pay_error"), TextSystem.GetText("pay_error_description"), UIManager.DialogOption["Yes"], function(option)
                --UnityEngine.Application.Quit();
            end);
        elseif event == UserSystem.Events.SDKLogoutSuccess then
            UnityEngine.Application.Quit();
        end
    end
end

function UserManager.Login(callback)
    loginCallback = callback;
    if userSystem.Instance:HasLogined() then
        fsm:init();
        --return true;
    else
        userSystem.Instance:Login();
        --return false;
    end
end

