function UserManager.OnAuth()
    HttpNetworkManager.Auth(function()
        -- 如果验证成功，则登录。
        fsm:login();
    end);
end

function UserManager.OnLogin()
    HttpNetworkManager.Login(function(response)
        loginResponse = cjson.decode(tostring(response));
        -- 如果登录成功，则进入大厅。
        fsm:done();
    end);
end

function UserManager.OnDone()
    if loginCallback ~= nil then
        loginCallback(loginResponse);
    end
end
